sysevent_in_email_action.script:
(function runAction(/*GlideRecord*/ current, /*GlideRecord*/ event, /*EmailWrapper*/ email, /*ScopedEmailLogger*/ logger, /*EmailClassifier*/ classifier) {

    gs.info('CLM NT Email Approval: Triggered for approval ' + current.getUniqueValue() + ' | Subject: ' + email.subject);

    // 1. Verify this approval belongs to a Non-Trade PAN Request; otherwise let later actions handle it
    var panSysId = (current.getValue('document_id') || current.getValue('sysapproval') || '') + '';
    var panGr    = new GlideRecord('x_birl3_clm_nt_pan_request');
    if (!panSysId || !panGr.get(panSysId)) {
        return;
    }

    // 2. Strip external warnings, watermark, quoted threads & signatures
    function parseInboundReply(subjectStr, bodyStr) {
        var txt = (bodyStr || '').toString().replace(/\r\n/g, '\n');

        // Cut off ServiceNow watermark & quoted reply headers
        txt = txt.split(/\n\s*(?:Ref\s*:|From\s*:|Sent\s*:|On .+ wrote:|-----Original Message-----|________________________________)/i)[0];

        // Strip Microsoft / Checkpoint external email warning banners
        txt = txt.replace(/^.*You don't often get email from[^\n]*\n?/gim, '');
        txt = txt.replace(/^.*Learn why this is important[^\n]*\n?/gim, '');
        txt = txt.replace(/^.*CAUTION:\s*This email originated from outside of the organization\.[^\n]*\n?/gim, '');
        txt = txt.replace(/^.*Do not click links or open attachments unless you recognize the sender[^\n]*\n?/gim, '');
        txt = txt.replace(/^.*\[?External(?:\s+Email)?\]?\s*:?\s*\n?/gim, '');

        // Cut off email signature blocks
        txt = txt.split(/\n\s*(?:Regards|Best\s+regards|Warm\s+regards|Kind\s+regards|Thanks(?:\s*(?:&|and)\s*regards)?|Thank\s+you|Sincerely|Cheers|--+|___+)\s*,?\s*(?:\n|$)/i)[0];
        txt = txt.trim();

        // Detect decision from subject OR cleaned body
        var subj = (subjectStr || '').toString().toLowerCase();
        var decision = '';
        if (subj.indexOf('approve') > -1 || /^(?:approve|approved)\b/i.test(txt)) {
            decision = 'approved';
        } else if (subj.indexOf('reject') > -1 || /^(?:reject|rejected)\b/i.test(txt)) {
            decision = 'rejected';
        }

        // Strip bare decision keyword so "Approved" alone isn't duplicated as a comment
        var cleanComment = txt.replace(/^(?:approve|approved|reject|rejected)\s*[:\-–—.]?\s*/i, '').trim();

        return {
            decision: decision,
            comment:  cleanComment
        };
    }

    var parsed       = parseInboundReply(email.subject, email.body_text);
    var decision     = parsed.decision;
    var replyComment = parsed.comment;

    if (!decision) {
        gs.info('CLM NT Email Approval skipped: no approve/reject keyword found.');
        return;
    }

    // 3. Verify sender is the assigned approver (or active delegate)
    var senderId = email.from_sys_id;
    if (senderId && current.getValue('approver') !== senderId) {
        var nowUtc = new GlideDateTime().getValue();
        var delGr  = new GlideRecord('sys_user_delegate');
        delGr.addQuery('user', current.getValue('approver'));
        delGr.addQuery('delegate', senderId);
        delGr.addQuery('approvals', true);
        delGr.addQuery('starts', '<=', nowUtc);
        delGr.addQuery('ends', '>=', nowUtc);
        delGr.setLimit(1);
        delGr.query();
        if (!delGr.hasNext()) {
            gs.info('CLM NT Email Approval skipped: sender (' + email.from + ') is not approver or active delegate.');
            return;
        }
    }

    // 4. Limit Calculation & Allocation Helpers
    function segKey(t) {
        t = (t || '').toString().toLowerCase();
        if (t.indexOf('cement') !== -1) return 'Cement';
        if (t.indexOf('rmc') !== -1)    return 'RMC';
        if (t.indexOf('bpd') !== -1)    return 'BPD';
        return '';
    }

    function getSiteCode(sGr) {
        var code = (sGr.getValue('customer_code') || '') + '';
        if (!code && sGr.isValidField('customer_site_code') && sGr.customer_site_code) {
            code = sGr.customer_site_code.customer_code_sap ? (sGr.customer_site_code.customer_code_sap + '') : '';
        }
        return code;
    }

    function getPanLimitContext(bId, panVal) {
        var reqMap = {};
        var sGr = new GlideRecord('x_birl3_clm_nt_site_request');
        sGr.addQuery('pan_request', bId);
        sGr.query();
        while (sGr.next()) {
            var code = getSiteCode(sGr);
            var seg  = sGr.isValidField('segment') ? segKey(sGr.getDisplayValue('segment')) : '';
            reqMap[code + '|' + seg] = parseFloat(sGr.getValue('requested_limit') || sGr.getValue('site_desired_limit')) || 0;
        }

        var other = 0, matched = 0;
        var seen = {}, claimed = {};
        var cGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
        cGr.addQuery('pan', panVal);
        cGr.addQuery('cg1', 'N01');
        cGr.query();
        while (cGr.next()) {
            var cCode  = (cGr.getValue('customer_code_sap') || '') + '';
            var cSeg   = segKey(cGr.getDisplayValue('segment'));
            var dedupe = cCode ? (cCode + '|' + cSeg) : cGr.getUniqueValue();
            if (seen[dedupe]) continue;
            seen[dedupe] = true;

            var key = cCode + '|' + cSeg;
            if (reqMap[key] === undefined && reqMap[cCode + '|'] !== undefined) key = cCode + '|';
            var isReq = (reqMap[key] !== undefined && !claimed[key]);

            if (isReq) {
                claimed[key] = true;
                matched += reqMap[key];
            } else {
                other += parseFloat(cGr.getValue('cr_limit') || cGr.getValue('credit_limit')) || 0;
            }
        }

        return {
            minLimit: Math.round(other),
            maxLimit: Math.round(other + matched)
        };
    }

    function allocateInteger(items, pool) {
        var n = items.length;
        if (!n) return [];
        var totReq = 0;
        items.forEach(function(it) { totReq += it.req; });

        var rows = items.map(function(it, i) {
            var share = totReq > 0 ? it.req / totReq : 1 / n;
            var raw   = pool * share;
            var base  = Math.floor(raw);
            return { i: i, base: base, frac: raw - base, req: it.req, code: it.code || '' };
        });

        var used = 0;
        rows.forEach(function(r) { used += r.base; });
        var left = pool - used;

        var order = rows.slice().sort(function(a, b) {
            if (Math.abs(a.frac - b.frac) > 1e-9) return b.frac - a.frac;
            if (a.req !== b.req) return b.req - a.req;
            return a.code < b.code ? -1 : (a.code > b.code ? 1 : 0);
        });
        for (var k = 0; k < left && k < order.length; k++) order[k].base += 1;

        return rows.map(function(r) { return r.base; });
    }

    function distributeApprovedLimitToSites(bId, panApprovedVal, minLimit) {
        var pool     = Math.max(0, Math.round(panApprovedVal - minLimit));
        var siteList = [];
        var sGr      = new GlideRecord('x_birl3_clm_nt_site_request');
        sGr.addQuery('pan_request', bId);
        sGr.query();
        while (sGr.next()) {
            var reqLim = parseFloat(sGr.getValue('requested_limit') || sGr.getValue('site_desired_limit')) || 0;
            siteList.push({
                sys_id: sGr.getUniqueValue(),
                req:    Math.max(0, reqLim),
                code:   getSiteCode(sGr)
            });
        }

        var alloc = allocateInteger(siteList, pool);
        for (var i = 0; i < siteList.length; i++) {
            var siteUpd = new GlideRecord('x_birl3_clm_nt_site_request');
            if (siteUpd.get(siteList[i].sys_id)) {
                siteUpd.setValue('approved_limit', alloc[i]);
                siteUpd.update();
            }
        }
    }

    var approverDisplay = current.approver ? current.approver.getDisplayValue() : 'Approver';

    // 5. Execute Approval or Rejection
    if (decision === 'approved') {
        var panCtx      = getPanLimitContext(panSysId, (panGr.getValue('pan') || '') + '');
        var approvedPan = panCtx.maxLimit;
        if (approvedPan <= 0) {
            approvedPan = Math.round(parseFloat(panGr.getValue('total_requested_limit') || panGr.getValue('total_desired_limit')) || 0);
        }

        var existingApproved = Math.round(parseFloat(panGr.getValue('total_approved_limit')) || 0);
        if (existingApproved > 0 && existingApproved < approvedPan) {
            approvedPan = existingApproved;
        }

        panGr.setValue('total_approved_limit', approvedPan);
        var appNote = 'Email Approver Decision: Approved by ' + approverDisplay;
        appNote    += '\nApproved PAN Limit: INR ' + approvedPan;
        appNote    += '\nAllocated to requested sites: INR ' + Math.max(0, approvedPan - panCtx.minLimit);
        if (replyComment) appNote += '\nComments: ' + replyComment;
        panGr.comments = appNote;
        panGr.update();

        distributeApprovedLimitToSites(panSysId, approvedPan, panCtx.minLimit);

        if (current.isValidField('approval_journal_column') && approvedPan > 0) {
            current.approval_journal_column = approvedPan.toString();
        }
        current.comments = replyComment || 'Approved via Email';
        current.setValue('state', 'approved');
        current.update();
        gs.info('CLM NT Email Approval: Successfully approved ' + panGr.getValue('number') + ' with limit ' + approvedPan);
    } else if (decision === 'rejected') {
        panGr.setValue('total_approved_limit', 0);
        var rejNote = 'Email Approver Decision: Rejected by ' + approverDisplay;
        if (replyComment) rejNote += '\nComments: ' + replyComment;
        panGr.comments = rejNote;
        panGr.update();

        var sRej = new GlideRecord('x_birl3_clm_nt_site_request');
        sRej.addQuery('pan_request', panSysId);
        sRej.query();
        while (sRej.next()) {
            sRej.setValue('approved_limit', 0);
            sRej.update();
        }

        current.comments = replyComment || 'Rejected via Email';
        current.setValue('state', 'rejected');
        current.update();
        gs.info('CLM NT Email Approval: Successfully rejected ' + panGr.getValue('number'));
    }

    event.state = 'stop_processing';

})(current, event, email, logger, classifier);
